//! Flattened JSON locale catalogs (`key.path` -> text), `I18n::t` / `t_args`, plural rules.
//! Keys are the original app's catalog keys verbatim; English text equals the original string.
//! Missing keys fall back to English, then to the key itself.
//!
//! Catalogs live in `src/locales/<code>.json` (generated by `scripts/import_locales.py`) and are
//! embedded with `include_str!`. Plurals follow i18next: `key_zero/_one/_two/_few/_many/_other`.

use std::collections::HashMap;

use intl_pluralrules::{PluralCategory, PluralRuleType, PluralRules};
use unic_langid::LanguageIdentifier;

macro_rules! catalogs {
    ($($code:literal),* $(,)?) => {
        /// (code, embedded JSON) for every shipped locale.
        const CATALOGS: &[(&str, &str)] =
            &[$(($code, include_str!(concat!("locales/", $code, ".json")))),*];
    };
}

catalogs!(
    "en", "ru", "zh", "ja", "ko", "es", "hi", "pt", "fr", "ar", "bn", "ur", "id", "de", "it", "tr",
    "vi", "pl", "fa", "th", "uk", "nl", "ta", "te", "mr", "fil", "ms", "sw", "ro"
);

/// Native display names, in the order shown by pickers.
const NATIVE_NAMES: &[(&str, &str)] = &[
    ("en", "English"),
    ("ru", "Русский"),
    ("zh", "中文"),
    ("ja", "日本語"),
    ("ko", "한국어"),
    ("es", "Español"),
    ("hi", "हिन्दी"),
    ("pt", "Português"),
    ("fr", "Français"),
    ("ar", "العربية"),
    ("bn", "বাংলা"),
    ("ur", "اردو"),
    ("id", "Bahasa Indonesia"),
    ("de", "Deutsch"),
    ("it", "Italiano"),
    ("tr", "Türkçe"),
    ("vi", "Tiếng Việt"),
    ("pl", "Polski"),
    ("fa", "فارسی"),
    ("th", "ไทย"),
    ("uk", "Українська"),
    ("nl", "Nederlands"),
    ("ta", "தமிழ்"),
    ("te", "తెలుగు"),
    ("mr", "मराठी"),
    ("fil", "Filipino"),
    ("ms", "Bahasa Melayu"),
    ("sw", "Kiswahili"),
    ("ro", "Română"),
];

/// Locales whose scripts need shaping/bidi that stock egui text layout lacks.
const EXPERIMENTAL: &[&str] = &["ar", "fa", "ur", "bn", "hi", "mr", "ta", "te", "th"];

/// `(code, native_name)` for every shipped locale.
pub fn available_locales() -> Vec<(&'static str, &'static str)> {
    NATIVE_NAMES.to_vec()
}

/// True if `code` renders poorly in egui without complex-script shaping (ar fa ur bn hi mr ta te th).
pub fn experimental(code: &str) -> bool {
    EXPERIMENTAL.contains(&code)
}

/// Right-to-left locales (no bidi support yet; informational).
pub fn is_rtl(code: &str) -> bool {
    matches!(code, "ar" | "fa" | "ur")
}

pub fn is_supported(code: &str) -> bool {
    CATALOGS.iter().any(|(c, _)| *c == code)
}

/// Map a system/BCP-47 tag (`en-US`, `zh_Hans_CN`, `tl-PH`) to a shipped code.
pub fn match_locale(tag: &str) -> Option<&'static str> {
    let primary = tag.split(['-', '_', '.']).next()?.to_ascii_lowercase();
    let primary = match primary.as_str() {
        "tl" => "fil",
        "in" => "id",
        "nb" | "nn" => return None,
        p => p,
    };
    CATALOGS.iter().map(|(c, _)| *c).find(|c| *c == primary)
}

/// Detected system locale, falling back to `en`.
pub fn system_locale() -> &'static str {
    sys_locale::get_locale()
        .as_deref()
        .and_then(match_locale)
        .unwrap_or("en")
}

/// Resolve a stored preference: `system` or unknown codes fall back as described above.
pub fn resolve_locale(pref: &str) -> &'static str {
    if pref != "system" {
        if let Some(c) = match_locale(pref) {
            return c;
        }
    }
    if pref == "system" {
        system_locale()
    } else {
        "en"
    }
}

fn parse(code: &str) -> HashMap<String, String> {
    CATALOGS
        .iter()
        .find(|(c, _)| *c == code)
        .and_then(|(_, json)| serde_json::from_str(json).ok())
        .unwrap_or_default()
}

fn category_suffix(locale: &str, n: u64) -> &'static str {
    let rules = locale
        .parse::<LanguageIdentifier>()
        .ok()
        .and_then(|l| PluralRules::create(l, PluralRuleType::CARDINAL).ok());
    match rules.and_then(|r| r.select(n).ok()) {
        Some(PluralCategory::ZERO) => "zero",
        Some(PluralCategory::ONE) => "one",
        Some(PluralCategory::TWO) => "two",
        Some(PluralCategory::FEW) => "few",
        Some(PluralCategory::MANY) => "many",
        Some(PluralCategory::OTHER) => "other",
        // Locale unknown to the plural tables (e.g. fil): singular is exactly 1.
        None => {
            if n == 1 {
                "one"
            } else {
                "other"
            }
        }
    }
}

#[derive(Debug, Default, Clone)]
pub struct I18n {
    /// Active locale code, e.g. `en`, `de`.
    pub locale: String,
    pub(crate) active: HashMap<String, String>,
    pub(crate) english: HashMap<String, String>,
}

impl I18n {
    /// English-only instance.
    pub fn english() -> I18n {
        I18n::load("en")
    }

    /// Load `locale` (unknown codes become `en`) plus the English fallback catalog.
    pub fn load(locale: &str) -> I18n {
        let code = match_locale(locale).unwrap_or("en");
        let english = parse("en");
        let active = if code == "en" {
            HashMap::new()
        } else {
            parse(code)
        };
        I18n {
            locale: code.to_string(),
            active,
            english,
        }
    }

    /// Load from a stored preference (`system` allowed).
    pub fn from_pref(pref: &str) -> I18n {
        I18n::load(resolve_locale(pref))
    }

    /// Switch language in place.
    pub fn set_locale(&mut self, locale: &str) {
        *self = I18n::load(locale);
    }

    /// Number of keys in the active catalog (English when active is English).
    pub fn key_count(&self) -> usize {
        if self.active.is_empty() {
            self.english.len()
        } else {
            self.active.len()
        }
    }

    pub fn has(&self, key: &str) -> bool {
        self.active.contains_key(key) || self.english.contains_key(key)
    }

    fn lookup(&self, key: &str) -> Option<&String> {
        self.active.get(key).or_else(|| self.english.get(key))
    }

    /// Text for `key` in the active locale.
    pub fn t(&self, key: &str) -> String {
        self.lookup(key).cloned().unwrap_or_else(|| key.to_string())
    }

    /// `t` with `{{name}}` placeholders replaced.
    pub fn t_args(&self, key: &str, args: &[(&str, &str)]) -> String {
        interpolate(self.t(key), args)
    }

    /// Plural-aware lookup: picks `key_<category>` for `n` (active locale rules), falling back to
    /// `key_other`, then English, then plain `key`. `{{count}}` is filled with `n`.
    pub fn t_count(&self, key: &str, n: u64) -> String {
        self.t_count_args(key, n, &[])
    }

    pub fn t_count_args(&self, key: &str, n: u64, args: &[(&str, &str)]) -> String {
        let loc = if self.locale.is_empty() {
            "en"
        } else {
            self.locale.as_str()
        };
        let tries = [
            (&self.active, category_suffix(loc, n)),
            (&self.active, "other"),
            (&self.english, category_suffix("en", n)),
            (&self.english, "other"),
        ];
        let text = tries
            .iter()
            .find_map(|(m, suf)| m.get(&format!("{key}_{suf}")))
            .or_else(|| self.lookup(key))
            .cloned()
            .unwrap_or_else(|| key.to_string());
        let count = n.to_string();
        let mut all: Vec<(&str, &str)> = vec![("count", count.as_str())];
        all.extend_from_slice(args);
        interpolate(text, &all)
    }
}

fn interpolate(mut s: String, args: &[(&str, &str)]) -> String {
    for (k, v) in args {
        s = s.replace(&format!("{{{{{k}}}}}"), v);
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_locale_parses_and_en_is_big() {
        for (code, json) in CATALOGS {
            let m: HashMap<String, String> =
                serde_json::from_str(json).unwrap_or_else(|e| panic!("{code}: {e}"));
            assert!(m.len() > 1000, "{code} has {} keys", m.len());
        }
        assert_eq!(CATALOGS.len(), 29);
        assert_eq!(NATIVE_NAMES.len(), 29);
        assert!(I18n::english().key_count() > 1000);
        assert_eq!(I18n::english().t("common.actions.save"), "Save");
    }

    #[test]
    fn fallback_order_and_args() {
        let mut i = I18n::load("de");
        assert_eq!(i.locale, "de");
        i.active.insert("only.de".into(), "Hallo {{who}}".into());
        i.english.insert("only.en".into(), "Hello".into());
        assert_eq!(i.t("only.de"), "Hallo {{who}}");
        assert_eq!(i.t_args("only.de", &[("who", "Welt")]), "Hallo Welt");
        assert_eq!(i.t("only.en"), "Hello");
        assert_eq!(i.t("no.such.key"), "no.such.key");
        assert_ne!(i.t("common.actions.save"), "common.actions.save");
        assert_eq!(I18n::load("xx").locale, "en");
    }

    #[test]
    fn plurals_en_ru_ar() {
        let mut en = I18n::english();
        en.english.insert("k_one".into(), "{{count}} item".into());
        en.english
            .insert("k_other".into(), "{{count}} items".into());
        assert_eq!(en.t_count("k", 1), "1 item");
        assert_eq!(en.t_count("k", 5), "5 items");

        let mut ru = I18n::load("ru");
        for (s, v) in [
            ("one", "{{count}} задача"),
            ("few", "{{count}} задачи"),
            ("many", "{{count}} задач"),
            ("other", "{{count}} задачи"),
        ] {
            ru.active.insert(format!("k_{s}"), v.into());
        }
        assert_eq!(ru.t_count("k", 1), "1 задача");
        assert_eq!(ru.t_count("k", 3), "3 задачи");
        assert_eq!(ru.t_count("k", 5), "5 задач");
        assert_eq!(ru.t_count("k", 21), "21 задача");

        let ar = I18n::load("ar");
        assert_eq!(category_suffix("ar", 0), "zero");
        assert_eq!(category_suffix("ar", 2), "two");
        assert_eq!(category_suffix("ar", 5), "few");
        assert_eq!(category_suffix("ar", 11), "many");
        assert_eq!(category_suffix("ar", 100), "other");
        // A real catalog key resolves with the count filled in.
        assert!(!ar.t_count("common.chat.context.count", 3).contains("{{"));
        // Falls back to _other when the locale lacks the category.
        let mut de = I18n::load("de");
        de.active.insert("z_other".into(), "{{count}} Stück".into());
        assert_eq!(de.t_count("z", 1), "1 Stück"); // "one" missing -> other
    }

    #[test]
    fn locale_resolution_and_flags() {
        assert_eq!(match_locale("en-US"), Some("en"));
        assert_eq!(match_locale("zh_Hans_CN"), Some("zh"));
        assert_eq!(match_locale("tl-PH"), Some("fil"));
        assert_eq!(match_locale("xx"), None);
        assert_eq!(resolve_locale("de"), "de");
        assert_eq!(resolve_locale("bogus"), "en");
        assert!(is_supported(resolve_locale("system")));
        assert!(experimental("ar") && experimental("th") && !experimental("ja"));
        assert_eq!(available_locales().len(), 29);
    }
}
